import{_ as a,o as e,c as n,a0 as t}from"./chunks/framework.BGyYNsHo.js";const h=JSON.parse('{"title":"Virtual junctions ([VIRTUAL_JUNCTIONS])","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/engine-modifications/05-virtual-junctions.md","filePath":"explanation/engine-modifications/05-virtual-junctions.md"}'),p={name:"explanation/engine-modifications/05-virtual-junctions.md"};function i(m,s,r,l,o,c){return e(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="virtual-junctions-virtual-junctions" tabindex="-1">Virtual junctions (<code>[VIRTUAL_JUNCTIONS]</code>) <a class="header-anchor" href="#virtual-junctions-virtual-junctions" aria-label="Permalink to &quot;Virtual junctions (`[VIRTUAL_JUNCTIONS]`)&quot;">​</a></h1><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>A slope change in a conduit must be split at a junction chamber. But an ordinary junction chamber introduces two numerical artifacts:</p><ol><li><strong>Artificial storage</strong>: its surface area is floored with the minimum <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>A</mi><mrow><mi>min</mi></mrow></msub><mo>=</mo><mn>1</mn><mn>2</mn><mi mathvariant="normal">.</mi><mn>5</mn><mn>6</mn><mn>6</mn><mtext> </mtext><mrow><mi mathvariant="normal">f</mi><msup><mi mathvariant="normal">t</mi><mn mathvariant="normal">2</mn></msup></mrow></mrow><annotation encoding="application/x-tex">A_{\\min} = 12.566\\ \\mathrm{ft^2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:0.964108em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">A</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mop">min</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord mathrm">6</span><span class="mord mathrm">6</span><span class="mord mspace"> </span><span class="mord textstyle uncramped"><span class="mord mathrm" style="margin-right:0.07778em;">f</span><span class="mord"><span class="mord mathrm">t</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span>, which adds a stagnation volume that &quot;blurs&quot; transients;</li><li><strong>Momentum break</strong>: the node acts as a small stagnation volume that interrupts the momentum transmission between the two conduits.</li></ol><p>A <strong>virtual junction</strong> (<code>[VIRTUAL_JUNCTIONS]</code>, section with name and invert elevation; everything else is derived) eliminates both artifacts for two collinear conduits of identical cross-section that meet at a slope break. A sealed node of identically null storage is declared. The eligibility rules are checked at input: exactly two links, both conduits; identical cross-sections (shape, dimensions, curve reference, number of barrels; Manning roughness may differ); both offsets at the node null with continuous invert; no lateral inflows of any kind; and dynamic wave routing method. Any violation is an input error.</p><h2 id="continuity-treatment" tabindex="-1">Continuity treatment <a class="header-anchor" href="#continuity-treatment" aria-label="Permalink to &quot;Continuity treatment&quot;">​</a></h2><p>A virtual junction is a sealed node of zero storage. Its head is updated with the free-surface formula using the natural half-link surface area contributed by its two conduits, <em>without</em> the minimum area floor (that floor is precisely the artificial storage the feature eliminates). When the natural area vanishes (dry pair, or surcharged pair with small slot width), the update falls to a pure flow-balance form of the surcharged update with <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>α</mi><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\alpha = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.0037em;">α</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span> and no floor. At convergence, <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>∑</mo><mi>Q</mi><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\sum Q = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.00001em;vertical-align:-0.25001em;"></span><span class="base textstyle uncramped"><span class="op-symbol small-op mop" style="top:-0.0000050000000000050004em;">∑</span><span class="mord mathit">Q</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span> at the node. The node is sealed: its head can rise above the crown without limit (like a chamber with a bolted lid), it never floods or ponds, and its volume and overflow are identically zero.</p><h2 id="momentum-treatment" tabindex="-1">Momentum treatment <a class="header-anchor" href="#momentum-treatment" aria-label="Permalink to &quot;Momentum treatment&quot;">​</a></h2><p>For a pass-through pair (one conduit entering, one leaving), the downstream conduit takes as upstream state the mean values of the upstream conduit in its Froude weighting (<em>upwinding</em> mechanism through the node), transporting the momentum advected through the node instead of resetting it. With <code>VIRTUAL_JUNCTION_MOMENTUM FULL</code> (default <code>BASIC</code>), a convective correction is additionally added to the inertia term of both conduits:</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">Δ</mi><msub><mi>Q</mi><mi>j</mi></msub><mo>=</mo><mi mathvariant="normal">Δ</mi><mi>t</mi><mspace width="0.16667em"></mspace><msub><mi>σ</mi><mi>j</mi></msub><mspace width="0.16667em"></mspace><mfrac><mrow><msub><mrow><mo fence="true">(</mo><msup><mover accent="true"><mi>U</mi><mo>¯</mo></mover><mrow><mn>2</mn></mrow></msup><mover accent="true"><mi>A</mi><mo>¯</mo></mover><mo fence="true">)</mo></mrow><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">b</mi></mrow></mrow></msub><mo>−</mo><msub><mrow><mo fence="true">(</mo><msup><mover accent="true"><mi>U</mi><mo>¯</mo></mover><mrow><mn>2</mn></mrow></msup><mover accent="true"><mi>A</mi><mo>¯</mo></mover><mo fence="true">)</mo></mrow><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">r</mi></mrow></mrow></msub></mrow><mrow><mi mathvariant="normal">Λ</mi></mrow></mfrac><mo separator="true">,</mo><mspace width="2em"></mspace><mi mathvariant="normal">Λ</mi><mo>=</mo><mfrac><mrow><msub><mi>L</mi><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">r</mi></mrow></mrow></msub><mo>+</mo><msub><mi>L</mi><mrow><mrow><mi mathvariant="normal">a</mi><mi mathvariant="normal">b</mi></mrow></mrow></msub></mrow><mrow><mn>2</mn></mrow></mfrac><mo separator="true">,</mo></mrow><annotation encoding="application/x-tex">\\Delta Q_j = \\Delta t\\,\\sigma_j\\, \\frac{\\left(\\bar U^{2}\\bar A\\right)_{\\mathrm{ab}} - \\left(\\bar U^{2}\\bar A\\right)_{\\mathrm{ar}}}{\\Lambda}, \\qquad \\Lambda = \\frac{L_{\\mathrm{ar}} + L_{\\mathrm{ab}}}{2},</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.6400100000000002em;"></span><span class="strut bottom" style="height:2.32601em;vertical-align:-0.686em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathrm">Δ</span><span class="mord"><span class="mord mathit">Q</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord mathrm">Δ</span><span class="mord mathit">t</span><span class="mord mspace thinspace"></span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">σ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord mspace thinspace"></span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">Λ</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.79001em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="minner"><span class="minner textstyle uncramped"><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit" style="margin-right:0.10903em;">U</span></span><span style="top:-0.25233em;margin-left:0.05556em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit">A</span></span><span style="top:-0.25233em;margin-left:0.27778em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="vlist"><span style="top:0.40001em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">b</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">−</span><span class="minner"><span class="minner textstyle uncramped"><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit" style="margin-right:0.10903em;">U</span></span><span style="top:-0.25233em;margin-left:0.05556em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord scriptstyle uncramped"><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mord accent"><span class="vlist"><span style="top:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="mord mathit">A</span></span><span style="top:-0.25233em;margin-left:0.27778em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="accent-body"><span>¯</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="style-wrap reset-textstyle textstyle uncramped" style="top:0em;"><span class="delimsizing size1">)</span></span></span><span class="vlist"><span style="top:0.40001em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">r</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:1em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mpunct">,</span><span class="mord mspace qquad"></span><span class="mord mathrm">Λ</span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">r</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">L</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathrm">a</span><span class="mord mathrm">b</span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mpunct">,</span></span></span></span></span></p><p>with <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>σ</mi><mi>j</mi></msub></mrow><annotation encoding="application/x-tex">\\sigma_j</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.716668em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">σ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.05724em;">j</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span> a Froude-shaped damping factor; the correction vanishes when the two conduits do not convey flow in the same direction through the node. Saddle pairs (both conduits toward the node) or crest pairs (both from the node) receive the zero-storage continuity treatment but not the directional momentum coupling. The pair is always solved together (it is not frozen by the convergence bypass) and a pair-level Courant check is added.</p><p>The usage guidance: virtual junctions are intended for slope breaks of small deflection; horizontal alignment changes should remain ordinary junction chambers with loss coefficients.</p>',12)])])}const u=a(p,[["render",i]]);export{h as __pageData,u as default};
